	["Menu-Creator-Misc-Button-RefreshGrids-Desc"] = {
		["en"] = "When you or others have used the move-all-props function, this button can instantly recalculate grid areas for all props to fix some unexpected behaviors when loading or unloading props",
		["fr"] = "Lorsque vous ou d'autres avez utilisé la fonction de déplacement de tous les props, ce bouton peut immédiatement recalculer les zones de grille pour tous les props afin de corriger certains comportements inattendus lors du chargement ou du déchargement des props",
		["de"] = "Wenn Sie oder andere die Funktion zum Verschieben aller Props verwendet haben, kann diese Schaltfläche sofort die Rasterbereiche für alle Props neu berechnen, um unerwartetes Verhalten beim Laden oder Entladen von Props zu beheben",
		["it"] = "Quando tu o altri avete utilizzato la funzione di spostamento di tutti i prop, questo pulsante può ricalcolare immediatamente le aree della griglia per tutti i prop, risolvendo alcuni comportamenti imprevisti durante il caricamento o lo scaricamento dei prop",
		["es"] = "Cuando tú u otras personas han utilizado la función de mover todos los props, este botón puede recalcular inmediatamente las áreas de la cuadrícula para todos los props y corregir algunos comportamientos inesperados al cargar o descargar props",
		["br"] = "Quando você ou outras pessoas usaram a função de mover todos os props, este botão pode recalcular imediatamente as áreas da grade para todos os props, corrigindo alguns comportamentos inesperados ao carregar ou descarregar props",
		["pl"] = "Gdy Ty lub inni użyli funkcji przenoszenia wszystkich propów, ten przycisk może natychmiast przeliczyć obszary siatki dla wszystkich propów, aby naprawić nieoczekiwane zachowania podczas ładowania lub rozładowywania propów",
		["ru"] = "Если вы или другие использовали функцию перемещения всех пропов, эта кнопка может мгновенно пересчитать сеточные области для всех пропов, чтобы исправить некоторые непредвиденные поведения при загрузке или выгрузке пропов",
		["ko"] = "사용자 또는 다른 사람이 모든 프로프 이동 기능을 사용한 경우, 이 버튼을 통해 모든 프로프의 그리드 영역을 즉시 다시 계산하여 프로프 로드 및 언로드 시 발생하는 일부 예기치 않은 동작을 수정할 수 있습니다",
		["zh"] = "當您或其他人使用了移動全部道具位置時,此按鈕可立即為所有道具重新劃分網格區域,以修復部分載入與卸載道具時的非預期行為",
		["jp"] = "自分または他の人がすべてのプロップを移動する機能を使用した場合、このボタンを押すことで、すべてのプロップのグリッド領域を即座に再計算し、プロップの読み込みや解除時に発生する一部の予期しない動作を修正できます",
		["mx"] = "Cuando tú u otras personas han utilizado la función de mover todos los props, este botón puede recalcular inmediatamente las áreas de la cuadrícula para todos los props y corregir algunos comportamientos inesperados al cargar o descargar props",
		["cn"] = "当您或其他人使用了移动全部道具位置时,这个按钮可立刻为所有道具重新划分网格区域,以修复一些加载和卸载道具的非预期行为"
	},

