function Client.Function.Translate.Add(key, data)
	if key and data then
		translation[key] = data
	end
end

function Client.Function.Translate.Get(text)
	local _ = nil
	if text and translation[text] then
		if translation[text][languageCode[Client.CurrentLanguage]] and translation[text][languageCode[Client.CurrentLanguage]] ~= "" then
			_ = translation[text][languageCode[Client.CurrentLanguage]]
		else
			_ = translation[text]["en"]
		end
	end
	return _ or ("Error " .. (text or ""))
end

function Client.Function.Translate.GetObjectLabelText(object)
	local objectHash = tonumber(object) or GetHashKey(object)
	if Creator.Data.ObjectLabels[objectHash] then
		local objectlabelText = GetLabelText(Creator.Data.ObjectLabels[objectHash])
		if objectlabelText ~= "NULL" then
			return objectlabelText
		end
	end
	if Creator.Data.ObjectModels[objectHash] then
		return Creator.Data.ObjectModels[objectHash]
	end
	if IsModelAVehicle(objectHash) then
		local vehicleName = GetLabelText(GetDisplayNameFromVehicleModel(objectHash))
		if vehicleName ~= "NULL" then
			return vehicleName
		end
	end
	return object
end

