function Client.Function.Translate.UpdateCurrentLanguage()
	CreateThread(function()
		while true do
			if Client.CurrentLanguage ~= GetCurrentLanguage() and not IsPauseMenuActive() then
				Client.CurrentLanguage = GetCurrentLanguage()
				Client.Menu.Main.Subtitle = string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Race.Title, Client.Menu.Race.Subtitle = Client.Function.Translate.Get("menu-race-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Player.Title, Client.Menu.Player.Subtitle = Client.Function.Translate.Get("menu-player-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Spawn.Main.Title, Client.Menu.Spawn.Main.Subtitle = Client.Function.Translate.Get("menu-spawn-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				for class, subMenu in pairs(Client.Menu.Spawn.Classes) do
					subMenu.Title, subMenu.Subtitle = Client.Function.Translate.Get(class), string.upper(Client.Function.Translate.Get("menu-items"))
				end
				Client.Menu.Vehicle.Main.Title, Client.Menu.Vehicle.Main.Subtitle = Client.Function.Translate.Get("menu-vehicle-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Vehicle.Custom.Main.Subtitle = string.upper(Client.Function.Translate.Get("menu-vehicle-custom"))
				Client.Menu.Vehicle.Custom.Upgrade.Subtitle = string.upper(Client.Function.Translate.Get("menu-vehicle-custom-upgrades"))
				Client.Menu.Vehicle.Custom.BodyPart.Subtitle = string.upper(Client.Function.Translate.Get("menu-vehicle-custom-bodyparts"))
				Client.Menu.Vehicle.Custom.Respray.Subtitle = string.upper(Client.Function.Translate.Get("menu-vehicle-custom-respray"))
				Client.Menu.Vehicle.Custom.Wheel.Subtitle = string.upper(Client.Function.Translate.Get("menu-vehicle-custom-wheels"))
				Client.Menu.Ped.Main.Title, Client.Menu.Ped.Main.Subtitle = Client.Function.Translate.Get("menu-ped-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Ped.Skin.Main.Subtitle = string.upper(Client.Function.Translate.Get("menu-ped-skin"))
				Client.Menu.Ped.Skin.Face.Subtitle = string.upper(Client.Function.Translate.Get("menu-ped-skin-face"))
				Client.Menu.Ped.Skin.Component.Subtitle = string.upper(Client.Function.Translate.Get("menu-ped-skin-component"))
				Client.Menu.Ped.Skin.Prop.Subtitle = string.upper(Client.Function.Translate.Get("menu-ped-skin-prop"))
				Client.Menu.Ped.Skin.Overlay.Subtitle = string.upper(Client.Function.Translate.Get("menu-ped-skin-overlay"))
				Client.Menu.Ped.Skin.Tattoo.Main.Subtitle = string.upper(Client.Function.Translate.Get("menu-ped-skin-tattoo"))
				for zoneName, subMenu in pairs(Client.Menu.Ped.Skin.Tattoo.Zones) do
					subMenu.Subtitle = string.upper(Client.Function.Translate.Get("skin-tattoo-" .. zoneName:gsub("^ZONE_", ""):lower():gsub("_", "-")))
				end
				Client.Menu.Ped.Animal.Title, Client.Menu.Ped.Animal.Subtitle = Client.Function.Translate.Get("menu-ped-animal"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Ped.AddOn.Title, Client.Menu.Ped.AddOn.Subtitle = Client.Function.Translate.Get("menu-ped-add-on"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Weapon.Main.Title, Client.Menu.Weapon.Main.Subtitle = Client.Function.Translate.Get("menu-weapon-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Weapon.Category.Subtitle = string.upper(Client.Function.Translate.Get("menu-weapon-category"))
				Client.Menu.World.Main.Title, Client.Menu.World.Main.Subtitle = Client.Function.Translate.Get("menu-world-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.World.Weather.Title, Client.Menu.World.Weather.Subtitle = Client.Function.Translate.Get("menu-world-weather"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.World.Time.Title, Client.Menu.World.Time.Subtitle = Client.Function.Translate.Get("menu-world-time"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.World.Teleport.Title, Client.Menu.World.Teleport.Subtitle = Client.Function.Translate.Get("menu-world-teleport"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Record.Title, Client.Menu.Record.Subtitle = Client.Function.Translate.Get("menu-record-options"), string.upper(Client.Function.Translate.Get("menu-items"))
				Client.Menu.Misc.Title, Client.Menu.Misc.Subtitle = Client.Function.Translate.Get("menu-misc-options"), string.upper(Client.Function.Translate.Get("menu-items"))

				Creator.Menu.Main.Title, Creator.Menu.Main.Subtitle = Client.Function.Translate.Get("Menu-Creator-Main-Title"), string.upper(Client.Function.Translate.Get("Menu-Creator-Main-Subtitle"))
				Creator.Menu.RaceDetail.Main.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-RaceDetail-Main-Subtitle"))
				Creator.Menu.RaceDetail.Class.Main.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-RaceDetail-Class-Subtitle"))
				for classid = 0, 27 do
					Creator.Menu.RaceDetail.Class.Vehicles[classid].Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-RaceDetail-Class-" .. classid))
				end
				for classid = 0, 27 do
					if Creator.Track.Current.AvailableVehicles[classid] then
						for i = 1, #Creator.Track.Current.AvailableVehicles[classid].vehicles do
							Creator.Track.Current.AvailableVehicles[classid].vehicles[i].name = GetLabelText(GetDisplayNameFromVehicleModel(Creator.Track.Current.AvailableVehicles[classid].vehicles[i].hash))
						end
					end
				end
				Creator.Menu.Placement.Main.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Main-Subtitle"))
				Creator.Menu.Placement.StartingGrid.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-StartingGrid-Subtitle"))
				Creator.Menu.Placement.Checkpoint.Main.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Checkpoint-Main-Subtitle"))
				Creator.Menu.Placement.Checkpoint.ExtraRandomSetting.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Checkpoint-ExtraRandomSetting-Subtitle"))
				Creator.Menu.Placement.Prop.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Prop-Subtitle"))
				Creator.Menu.Placement.Template.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Template-Subtitle"))
				Creator.Menu.Placement.MoveAll.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-MoveAll-Subtitle"))
				Creator.Menu.Placement.Fixture.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Fixture-Subtitle"))
				Creator.Menu.Placement.Firework.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Placement-Firework-Subtitle"))
				Creator.Menu.Multiplayer.Main.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Multiplayer-Main-Subtitle"))
				Creator.Menu.Multiplayer.Invite.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Multiplayer-Invite-Subtitle"))
				Creator.Menu.Weather.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Weather-Subtitle"))
				Creator.Menu.Time.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Time-Subtitle"))
				Creator.Menu.Misc.Subtitle = string.upper(Client.Function.Translate.Get("Menu-Creator-Misc-Subtitle"))

				if Client.IsInCreator and not Client.IsCreatorInQuiting and Creator.GlobalVar.EnableTest and Creator.GlobalVar.TipsRendered then
					ClearAllHelpMessages()
					BeginTextCommandDisplayHelp("THREESTRINGS")
					AddTextComponentSubstringPlayerName(Client.Function.Translate.Get("quit-test"))
					AddTextComponentSubstringPlayerName("")
					AddTextComponentSubstringPlayerName("")
					EndTextCommandDisplayHelp(0, true, false, -1)
				end

				Client.Function.Vehicle.SetAddOnNames()
				Client.Function.Vehicle.GetAllForMenu()
				Client.Function.Vehicle.SetSavedForMenu()
				Client.Function.Tattoo.InitData()
				Client.Function.Weapon.InitData()

				SendNUIMessage({
					action = "translate html",
					texts = Client.Function.Translate.GetHtmlTexts()
				})

				if Race.Status == "racing" or Race.Status == "spectating" then
					Race.Function.UpdatePauseMenuInfo()
				end

				TriggerServerEvent("server:core:setFlag", Client.CurrentLanguage)
			end
			Wait(0)
		end
	end)
end